mapper.select:
SELECT o.grant_id,o.grant_version,o.operation,o.attempts FROM auth_governance.grant_projection o JOIN auth_governance.access_grant g ON g.id=o.grant_id
WHERE  AND o.completed=false AND (g.version <> o.grant_version OR (o.attempts < 5 AND o.next_attempt_at <=clock_timestamp()))
ORDER BY o.created_at,o.grant_id,o.grant_version LIMIT #{limit}
